/**
 * 22:00 UTC on the 11th is already the 12th in Warsaw, and 21:00 UTC on the
 * 15th is the 15th there — the classic off-by-one this guards against.
 */
export const TIMED_UTC_FEED = `BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//Test//Rezervio//EN
BEGIN:VEVENT
UID:timed@example.com
DTSTART:20260911T220000Z
DTEND:20260915T210000Z
SUMMARY:Timed stay
END:VEVENT
END:VCALENDAR`;

